// TEMP DEBUG — delete this block once the responsive column scaling is
// confirmed correct. Draws the 96px margin / 12-column / 24px gutter
// design grid on top of every page, using the same --side-padding var the
// real layout uses, so it always reflects whatever the current formula is.
// A small toggle button (bottom-right, every page) shows/hides it; the
// choice is remembered in localStorage so it stays consistent while
// clicking between pages.
(function () {
  const STORAGE_KEY = 'design-grid-overlay-visible';

  const overlay = document.createElement('div');
  overlay.className = 'design-grid-overlay';
  overlay.setAttribute('aria-hidden', 'true');
  overlay.innerHTML =
    '<div class="design-grid-overlay__frame"></div>' +
    '<div class="design-grid-overlay__inner">' +
    '<div class="design-grid-overlay__col"></div>'.repeat(12) +
    '</div>';

  const toggle = document.createElement('button');
  toggle.type = 'button';
  toggle.className = 'design-grid-overlay-toggle';

  const setVisible = (visible) => {
    overlay.style.display = visible ? '' : 'none';
    toggle.textContent = visible ? 'Grid: on' : 'Grid: off';
    localStorage.setItem(STORAGE_KEY, visible ? '1' : '0');
  };

  toggle.addEventListener('click', () => {
    setVisible(overlay.style.display === 'none');
  });

  document.addEventListener('DOMContentLoaded', () => {
    document.body.appendChild(overlay);
    document.body.appendChild(toggle);
    setVisible(localStorage.getItem(STORAGE_KEY) !== '0');
  });
})();

// TEMP DEBUG — delete alongside the grid overlay above. A fixed, high-
// contrast black/white stripe pattern sitting just BEHIND the real header
// (z-index 999, one below the header's 1000) so .site-header__glass-blur's
// mask-image fade has something with hard edges to visibly show through —
// real scrolled content (photos, prose) rarely has an edge that sharp,
// which is why the same fade is much harder to spot against it. Toggle
// button sits right above the grid one; default off so it doesn't get in
// the way day-to-day.
(function () {
  const STORAGE_KEY = 'stripe-test-visible';

  const stripes = document.createElement('div');
  stripes.setAttribute('aria-hidden', 'true');
  stripes.style.cssText =
    'position:fixed;top:0;left:0;right:0;height:110px;z-index:500;' +
    'pointer-events:none;' +
    'background:repeating-linear-gradient(to right, black 0 20px, white 20px 40px);';

  const toggle = document.createElement('button');
  toggle.type = 'button';
  toggle.style.cssText =
    'position:fixed;right:16px;bottom:56px;z-index:100000;padding:8px 14px;' +
    'background:black;color:lime;border:1px solid rgba(0,255,0,0.5);' +
    'border-radius:4px;font:12px monospace;cursor:pointer;';

  const setVisible = (visible) => {
    stripes.style.display = visible ? '' : 'none';
    toggle.textContent = visible ? 'Stripe test: on' : 'Stripe test: off';
    localStorage.setItem(STORAGE_KEY, visible ? '1' : '0');
  };

  toggle.addEventListener('click', () => {
    setVisible(stripes.style.display === 'none');
  });

  document.addEventListener('DOMContentLoaded', () => {
    document.body.appendChild(stripes);
    document.body.appendChild(toggle);
    setVisible(localStorage.getItem(STORAGE_KEY) === '1');
  });
})();
